"""Register ten explicit missile retention decisions and fresh runtime proof without adding duplicate studies."""
import hashlib
import json
from pathlib import Path
from PIL import Image,ImageDraw,ImageFont
ROOT=Path(__file__).resolve().parents[1]


def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def save(p,value):
    newline='\r\n' if p.exists() and b'\r\n' in p.read_bytes() else '\n';p.write_bytes((json.dumps(value,indent=2)+'\n').replace('\n',newline).encode())


def main():
    docs=ROOT/'sources/docs/reconstruction/models';evidence_path=docs/'braccatian-missile-evidence.json';evidence=json.loads(evidence_path.read_text());assert len(evidence['records'])==10;verifier=ROOT/'sources/tools/blender/verify_braccatian_missile_retention.py';records=[];paths=[evidence_path,verifier];renders=meshes=0;max_position=max_normal=max_rgb=0.;min_iou=1.
    sheet=Image.new('RGB',(1500,660),(25,29,33));draw=ImageDraw.Draw(sheet);font=ImageFont.load_default(size=16);draw.text((15,10),'BRACCATIAN MISSILES | Reviewed and retained after fresh native / GLB verification',font=font,fill='white')
    for i,row in enumerate(evidence['records']):
        model=ROOT/row['model'];media=ROOT/'gallery/media/docs/assets/reconstruction/braccatian-refined/missile-retention'/row['slug'];validation=media/'validation.json';report=json.loads(validation.read_text());assert report['id']==row['id'] and report['key']==row['key'] and report['name']==row['name'] and report['decision']=='retained-after-focused-review'
        for ext in ['blend','glb']:assert sha(model.with_suffix('.'+ext))==row[ext+'_sha256']==report[ext+'_sha256']
        assert report['evidence_sha256']==sha(evidence_path) and report['verifier_sha256']==sha(verifier)
        for n,digest in report['verifier_dependencies_sha256'].items():assert sha(verifier.with_name(n))==digest
        assert report['native_mesh_count']==report['imported_mesh_count'];assert report['retained_native_geometry_uv_normals_preserved'] and report['alignment_helpers_preserved'] and report['effective_pbr_channels_preserved'];assert report['authored_clips']==[]
        for side in ['native','imported']:assert report[side+'_contract']['closed_positive_meshes']==report[side+'_mesh_count']
        for view,result in report['renders'].items():
            assert result['native_sha256']==sha(media/(view+'.png')) and result['imported_sha256']==sha(media/('imported-'+view+'.png'));min_iou=min(min_iou,result['silhouette_iou']);max_rgb=max(max_rgb,result['foreground_rgb_mean_difference_255'])
        assert len(report['renders'])==4 and report['legacy_descriptors_reviewed']==14
        max_position=max(max_position,report['maximum_native_imported_position_error']);max_normal=max(max_normal,report['maximum_corner_normal_error']);renders+=len(report['renders']);meshes+=report['native_mesh_count']
        reason=row['observed']+' Existing source and current model views show these major forms and divisions. No additional resolved external component justifies a new study at this source resolution; preserve the detailed first model. Exact hidden sections, transverse shape and material identities remain authored.'
        records.append(dict(id=row['id'],key=row['key'],name=row['name'],decision='retained-after-focused-review',reason=reason,model=row['model'],blend_sha256=row['blend_sha256'],glb_sha256=row['glb_sha256'],validation=validation.relative_to(ROOT).as_posix(),validation_sha256=sha(validation),legacy_descriptors_reviewed=14,native_mesh_count=report['native_mesh_count']))
        paths+=list(media.iterdir());im=Image.open(media/'front-quarter.png').convert('RGBA');im=im.crop(im.getchannel('A').getbbox());im.thumbnail((280,240));x=(i%5)*300;y=40+(i//5)*305;sheet.paste(im,(x+(300-im.width)//2,y+(240-im.height)//2),im);draw.text((x+10,y+250),row['key']+' '+row['name'],font=font,fill='white');draw.text((x+10,y+276),'Retained / runtime verified',fill=(170,190,200),font=ImageFont.load_default(size=14))
    overview=ROOT/'gallery/sheets/braccatian-missile-review.jpg';sheet.save(overview,quality=92)
    ledger=dict(issue=190,culture='braccatian',scope='All ten missiles: reviewed and retained unchanged, not ten new refined studies',evidence_sha256=sha(evidence_path),review_tool_sha256=sha(ROOT/'tools/review_braccatian_missile_evidence.py'),registration_tool_sha256=sha(Path(__file__)),overview=dict(path=overview.relative_to(ROOT).as_posix(),sha256=sha(overview)),records=records,totals=dict(models=10,new_studies=0,retained_closed_meshes=meshes,reviewed_legacy_descriptors=140,paired_renders=renders,minimum_render_iou=min_iou,maximum_runtime_position_error=max_position,maximum_corner_normal_error=max_normal,maximum_rgb_mean_difference_255=max_rgb),uncertainties=['Exact hidden geometry, profiles, source projection and forward-axis gameplay calibration remain authored/open','Fourteen source descriptor presentations do not establish a recovered operating/deployment clip; plume pixels are not solid geometry','Comms Killer faceting and HotBomb casting sections are existing interpretations at very small source resolution'])
    ledger_path=docs/'braccatian-missile-decisions.json';save(ledger_path,ledger);paths.append(ledger_path)
    lines=['# Braccatian missile review (#190)','', 'All ten missiles are retained after focused source and fresh runtime review. These are explicit unchanged-model decisions, not ten new refinements. Existing models already contain the larger visible forms, colour regions, collars, castings and meaningful service construction; the references do not establish more external machinery.','', 'All 140 descriptors were inspected, then freshly re-decoded and checked against the prior indexed/colour references. Missile files carry grayscale placeholder palettes: the actual `_MS/BUTTONS.256` game palette is required and its identity is verified. Original pixels stay private. Full Braccatian CDB/function evidence is bound; names/effect roles do not establish internal mechanisms. The completed Sci-Tek applicability audit contains no Braccatian preview binding.','', '| Model | Reason to retain the existing geometry | Closed meshes |','| --- | --- | ---: |']
    for row,record in zip(evidence['records'],records):lines.append(f"| {row['key']} {row['name']} | {row['observed']} | {record['native_mesh_count']} |")
    lines += ['',f"Actual Blender 4.5.15 native reopen and independent GLB import pass for {meshes} closed positive meshes and {renders} paired renders. Construction tests recheck profiles/dents, connected core/end/collar assemblies, exposed narrow waists, actual annular voids, fitted skins/slots/fasteners, original helper rotations and UV projections. Packed effective colour/roughness/metallic channels, normal directions, geometry bounds and hierarchy agree. Source Blend/GLB pairs remain byte-identical to the baseline.",'',f"All {renders} paired silhouettes have IoU {min_iou:.9f}. Maximum world position difference is {max_position:.9g}, helper error below 0.00001 and corner-normal difference {max_normal:.9g}; RGB mean difference below {max_rgb:.9g}/255. All native/imported quarter, reverse, plan and detail views were inspected. Source/body comparisons were inspected against all fourteen original presentations, without claiming an exact recovered camera.",'', 'No model contains an authored operating clip. Bright plume frames remain effect evidence, not new solid exhaust geometry. Shorter body presentations do not justify invented unfolding components. Source direction, exact timing/sequence and gameplay orientation calibration are not newly recovered here. Existing Comms Killer faceting and HotBomb transverse casting shape remain qualified interpretations.','', '![Reviewed retained missiles](../../../../gallery/sheets/braccatian-missile-review.jpg)','', 'Reproduce evidence with `python tools/review_braccatian_missile_evidence.py --legacy-root <legacy-root>`. Run the fresh Blender verifier `sources/tools/blender/verify_braccatian_missile_retention.py -- --models <slugs>` without regenerating or overwriting accepted sources, then `python tools/register_braccatian_missile_review.py`. Per-model decisions bind exact source/report hashes in `braccatian-missile-decisions.json`; actual validation and new review renders are under `gallery/media/docs/assets/reconstruction/braccatian-refined/missile-retention/<slug>/`.','', 'This closes the ten missile decisions. The separate final all-38 Braccatian scope/source/animation/gallery audit remains required before declaring the persistent goal complete.','']
    review=docs/'braccatian-missile-review.md';review.write_text('\n'.join(lines),encoding='utf-8');paths.append(review)
    layout_path=ROOT/'project/layout.json';layout=json.loads(layout_path.read_text());destinations={x['destination'] for x in layout['files']}
    for p in sorted(set(paths)):
        assert p.is_file();destination=p.relative_to(ROOT).as_posix()
        if destination in destinations:continue
        media=destination.startswith('gallery/media/');original=destination.removeprefix('gallery/media/' if media else 'sources/');assert not any(x['original']==original for x in layout['files']);layout['files'].append(dict(original=original,destination=destination,role='media' if media else 'source',ownership='authored'));destinations.add(destination)
    save(layout_path,layout);print('BRACCATIAN_MISSILE_DECISIONS_REGISTERED',ledger['totals'])


if __name__=='__main__':main()
